"Content"],0)			else				if Item_AddNewItem(tPokerBoxGift_Pack[1]["DeleteItem"][1]["Id"],"") then					Sys_SaveActionFestivalLog(tPokerBoxGift_Cont["PackLog"])					Sys_BoxDialogTips(tPokerBoxGift_Text["Title"],tPokerBoxGift_Text["Msg"][2])						end							end					end	endend-- 物品使用函数function PokerBoxGift_UseeOpenPack(nItemId)	-- if not User_CheckClientType(tPokerBoxGift_Cont["HZflag"]) then		RewardTemplate_UseItem(tPokerBoxGift_Pack[1])	-- endend		-- 物品使用tItem[3300372] = tItem[3300372] or {}tItem[3300372]["Function"] = function(nItemId,sItemName)	PokerBoxGift_UseeOpenPack(nItemId)	end		-- table.insert(tSystem_PlayLogin_Func,PokerBoxGift_PlayerLoad)		